PRODUCTION_SOURCE = '"""\nOLA-047\nOracle Scheduler Lineage Production Composition\n\nSingle canonical composition surface for production lineage wiring.\n\nPurpose:\n- accept the existing production persistence router\n- accept the existing OLA-030 scheduler cycle callable\n- build one shared OLA-044 production wiring contract\n- expose the OLA-042 staged persistence router for injection into both the\n  live acquisition runtime and OLA-017\n- build OLA-045 completion bridge on the same shared wiring state\n- build OLA-046 scheduler lineage production adapter around the existing\n  OLA-030 scheduler cycle callable\n- preserve one shared lineage state across repeated scheduler cycles\n\nThis module performs composition only.\nIt does not alter scheduler kwargs, scheduler result projection, persistence\nsemantics, intelligence interpretation, scoring, alerts, Q Series handoff,\nauthorization, or execution.\n\nOracle remains permanently read-only.\n"""\n\nfrom __future__ import annotations\n\nfrom dataclasses import dataclass\nfrom typing import Any, Callable\n\nfrom .oracle_persisted_cohort_lineage_production_wiring_contract import (\n    OraclePersistedCohortLineageProductionWiringContract,\n)\nfrom .oracle_scheduler_cycle_lineage_completion_bridge import (\n    OracleSchedulerCycleLineageCompletionBridge,\n)\nfrom .oracle_scheduler_lineage_production_adapter import (\n    OracleSchedulerLineageProductionAdapter,\n)\n\n\nSCHEMA_VERSION = "OLA-047"\nENGINE_ID = "OLA-047"\n\nREAD_ONLY = True\nEXECUTION_ALLOWED = False\nEXECUTION_ADAPTER_RESOLVED = False\nEXECUTION_ADAPTER_INVOKED = False\nTRADE_AUTHORIZATION_ALLOWED = False\nORDER_PLACEMENT_ALLOWED = False\nFUNDS_MOVED = False\nPORTFOLIO_MUTATED = False\n\n\nclass SchedulerLineageProductionCompositionContractError(ValueError):\n    """Raised when OLA-047 composition input is malformed."""\n\n\nclass SchedulerLineageProductionCompositionInvariantError(RuntimeError):\n    """Raised when permanent OLA-047 invariants are violated."""\n\n\n@dataclass(frozen=True, slots=True)\nclass SchedulerLineageProductionCompositionReceipt:\n    schema_version: str\n    engine_id: str\n    production_persistence_router_preserved: bool\n    scheduler_cycle_callable_preserved: bool\n    staged_router_shared_with_production_wiring: bool\n    completion_bridge_shared_with_production_wiring: bool\n    scheduler_adapter_shared_with_completion_bridge: bool\n    read_only: bool\n    execution_allowed: bool\n    execution_adapter_resolved: bool\n    execution_adapter_invoked: bool\n    trade_authorization_allowed: bool\n    order_placement_allowed: bool\n    funds_moved: bool\n    portfolio_mutated: bool\n\n    def assert_invariants(self) -> None:\n        if self.schema_version != SCHEMA_VERSION:\n            raise SchedulerLineageProductionCompositionInvariantError(\n                "schema version invariant violated"\n            )\n\n        if self.engine_id != ENGINE_ID:\n            raise SchedulerLineageProductionCompositionInvariantError(\n                "engine identity invariant violated"\n            )\n\n        required = (\n            self.production_persistence_router_preserved,\n            self.scheduler_cycle_callable_preserved,\n            self.staged_router_shared_with_production_wiring,\n            self.completion_bridge_shared_with_production_wiring,\n            self.scheduler_adapter_shared_with_completion_bridge,\n        )\n\n        if required != (\n            True,\n            True,\n            True,\n            True,\n            True,\n        ):\n            raise SchedulerLineageProductionCompositionInvariantError(\n                "OLA-047 shared production composition invariant violated"\n            )\n\n        authority = (\n            self.read_only,\n            self.execution_allowed,\n            self.execution_adapter_resolved,\n            self.execution_adapter_invoked,\n            self.trade_authorization_allowed,\n            self.order_placement_allowed,\n            self.funds_moved,\n            self.portfolio_mutated,\n        )\n\n        if authority != (\n            True,\n            False,\n            False,\n            False,\n            False,\n            False,\n            False,\n            False,\n        ):\n            raise SchedulerLineageProductionCompositionInvariantError(\n                "OLA-047 read-only authority invariants violated"\n            )\n\n\nclass OracleSchedulerLineageProductionComposition:\n    read_only = True\n    execution_allowed = False\n\n    def __init__(\n        self,\n        *,\n        production_persistence_router: Any,\n        scheduler_cycle_callable: Callable[..., Any],\n    ) -> None:\n        route_batch = getattr(\n            production_persistence_router,\n            "route_batch",\n            None,\n        )\n\n        if not callable(route_batch):\n            raise SchedulerLineageProductionCompositionContractError(\n                "production_persistence_router must expose callable route_batch"\n            )\n\n        if not callable(scheduler_cycle_callable):\n            raise SchedulerLineageProductionCompositionContractError(\n                "scheduler_cycle_callable must be callable"\n            )\n\n        self._production_persistence_router = (\n            production_persistence_router\n        )\n        self._scheduler_cycle_callable = (\n            scheduler_cycle_callable\n        )\n\n        self._production_wiring = (\n            OraclePersistedCohortLineageProductionWiringContract(\n                production_persistence_router=(\n                    production_persistence_router\n                )\n            )\n        )\n\n        self._completion_bridge = (\n            OracleSchedulerCycleLineageCompletionBridge(\n                production_wiring=self._production_wiring\n            )\n        )\n\n        self._scheduler_adapter = (\n            OracleSchedulerLineageProductionAdapter(\n                scheduler_cycle_callable=(\n                    scheduler_cycle_callable\n                ),\n                lineage_completion_bridge=(\n                    self._completion_bridge\n                ),\n            )\n        )\n\n        self._receipt = (\n            SchedulerLineageProductionCompositionReceipt(\n                schema_version=SCHEMA_VERSION,\n                engine_id=ENGINE_ID,\n                production_persistence_router_preserved=(\n                    self._production_wiring\n                    .production_persistence_router\n                    is production_persistence_router\n                ),\n                scheduler_cycle_callable_preserved=(\n                    self._scheduler_adapter\n                    .scheduler_cycle_callable\n                    is scheduler_cycle_callable\n                ),\n                staged_router_shared_with_production_wiring=(\n                    self.staged_persistence_router\n                    is self._production_wiring\n                    .staged_persistence_router\n                ),\n                completion_bridge_shared_with_production_wiring=(\n                    self._completion_bridge.production_wiring\n                    is self._production_wiring\n                ),\n                scheduler_adapter_shared_with_completion_bridge=(\n                    self._scheduler_adapter\n                    .lineage_completion_bridge\n                    is self._completion_bridge\n                ),\n                read_only=READ_ONLY,\n                execution_allowed=EXECUTION_ALLOWED,\n                execution_adapter_resolved=(\n                    EXECUTION_ADAPTER_RESOLVED\n                ),\n                execution_adapter_invoked=(\n                    EXECUTION_ADAPTER_INVOKED\n                ),\n                trade_authorization_allowed=(\n                    TRADE_AUTHORIZATION_ALLOWED\n                ),\n                order_placement_allowed=(\n                    ORDER_PLACEMENT_ALLOWED\n                ),\n                funds_moved=FUNDS_MOVED,\n                portfolio_mutated=PORTFOLIO_MUTATED,\n            )\n        )\n\n        self._receipt.assert_invariants()\n\n    @property\n    def production_persistence_router(self) -> Any:\n        return self._production_persistence_router\n\n    @property\n    def scheduler_cycle_callable(\n        self,\n    ) -> Callable[..., Any]:\n        return self._scheduler_cycle_callable\n\n    @property\n    def production_wiring(\n        self,\n    ) -> OraclePersistedCohortLineageProductionWiringContract:\n        return self._production_wiring\n\n    @property\n    def staged_persistence_router(self):\n        return self._production_wiring.staged_persistence_router\n\n    @property\n    def completion_bridge(\n        self,\n    ) -> OracleSchedulerCycleLineageCompletionBridge:\n        return self._completion_bridge\n\n    @property\n    def scheduler_adapter(\n        self,\n    ) -> OracleSchedulerLineageProductionAdapter:\n        return self._scheduler_adapter\n\n    @property\n    def receipt(\n        self,\n    ) -> SchedulerLineageProductionCompositionReceipt:\n        return self._receipt\n'

TEST_SOURCE = 'from datetime import datetime, timezone\n\nfrom qseries_v2.oracle_intelligence.live_acquisition.oracle_scheduler_lineage_production_composition import (\n    OracleSchedulerLineageProductionComposition,\n)\nfrom qseries_v2.oracle_intelligence.live_acquisition.oracle_live_read_only_acquisition_runtime import (\n    CanonicalObservation,\n    ObservationRoutingEvidence,\n    RawSourceObservation,\n)\n\n\nT1 = datetime(\n    2026,\n    7,\n    14,\n    21,\n    0,\n    0,\n    tzinfo=timezone.utc,\n)\nT2 = datetime(\n    2026,\n    7,\n    14,\n    21,\n    0,\n    15,\n    tzinfo=timezone.utc,\n)\nT3 = datetime(\n    2026,\n    7,\n    14,\n    21,\n    0,\n    30,\n    tzinfo=timezone.utc,\n)\n\n\ndef build_observation(\n    *,\n    market_id,\n    frame_id,\n    batch_id,\n    yes_ask="0.6140",\n):\n    payload = {\n        "source_market_id": market_id,\n        "yes_bid_dollars": "0.0000",\n        "yes_bid_size_fp": "0.00",\n        "yes_ask_dollars": yes_ask,\n        "yes_ask_size_fp": "40.00",\n        "no_bid_dollars": "0.3860",\n        "no_ask_dollars": "0.0000",\n        "last_price_dollars": "0.0000",\n        "previous_yes_bid_dollars": "0.0000",\n        "previous_yes_ask_dollars": "0.6000",\n        "previous_price_dollars": "0.0000",\n        "volume_fp": "0.00",\n        "volume_24h_fp": "0.00",\n        "open_interest_fp": "0.00",\n        "liquidity_dollars": "0.0000",\n    }\n\n    raw = RawSourceObservation.create(\n        source_observation_id=(\n            "kalshi."\n            + market_id\n            + "."\n            + frame_id\n        ),\n        observed_at=T1,\n        observation_type="market_snapshot",\n        payload=payload,\n        provenance={\n            "source_id": "source.kalshi.market_data",\n            "frame_id": frame_id,\n        },\n    )\n\n    return CanonicalObservation.create(\n        source_id="source.kalshi.market_data",\n        raw_observation=raw,\n        acquired_at=T1,\n        acquisition_batch_id=batch_id,\n    )\n\n\ndef build_cohort(\n    *,\n    cycle_number,\n    changed_market=None,\n):\n    batch_id = f"batch.ola.047.{cycle_number}"\n\n    return tuple(\n        build_observation(\n            market_id=f"KXTEST-COMPOSE-{index}",\n            frame_id=f"{cycle_number}-{index}",\n            batch_id=batch_id,\n            yes_ask=(\n                "0.9700"\n                if changed_market\n                == f"KXTEST-COMPOSE-{index}"\n                else "0.6140"\n            ),\n        )\n        for index in range(1, 6)\n    )\n\n\nclass FakeProductionPersistenceRouter:\n    def __init__(self):\n        self.batch_calls = 0\n\n    def route_batch(\n        self,\n        observations,\n        routed_at,\n    ):\n        self.batch_calls += 1\n\n        return tuple(\n            ObservationRoutingEvidence.create(\n                observation_id=observation.observation_id,\n                routed_at=routed_at,\n                accepted=True,\n                route_id="fake.ola.047.persistence",\n                metadata={\n                    "test": "OLA-047",\n                },\n            )\n            for observation in observations\n        )\n\n    def __call__(\n        self,\n        observation,\n        routed_at,\n    ):\n        return ObservationRoutingEvidence.create(\n            observation_id=observation.observation_id,\n            routed_at=routed_at,\n            accepted=True,\n            route_id="fake.ola.047.persistence.single",\n            metadata={\n                "test": "OLA-047",\n            },\n        )\n\n\nclass FakeSchedulerCycleCallable:\n    def __init__(self):\n        self.call_count = 0\n        self.last_kwargs = None\n\n    def __call__(\n        self,\n        **kwargs,\n    ):\n        self.call_count += 1\n        self.last_kwargs = dict(kwargs)\n\n        return {\n            "schema_version": "OLA-017",\n            "engine_id": "OLA-017",\n            "cycle_status": "completed",\n            "canonical_count": 5,\n            "postgresql_routing_record_delta": 5,\n            "read_only": True,\n            "execution_allowed": False,\n            "scheduler_projection": "preserved",\n            "kwargs_echo": dict(kwargs),\n        }\n\n\ndef build_composition():\n    persistence_router = (\n        FakeProductionPersistenceRouter()\n    )\n    scheduler_callable = (\n        FakeSchedulerCycleCallable()\n    )\n\n    composition = (\n        OracleSchedulerLineageProductionComposition(\n            production_persistence_router=(\n                persistence_router\n            ),\n            scheduler_cycle_callable=(\n                scheduler_callable\n            ),\n        )\n    )\n\n    return (\n        composition,\n        persistence_router,\n        scheduler_callable,\n    )\n\n\ndef run_composition_identity_test():\n    (\n        composition,\n        persistence_router,\n        scheduler_callable,\n    ) = build_composition()\n\n    receipt = composition.receipt\n\n    assert receipt.schema_version == "OLA-047"\n    assert receipt.engine_id == "OLA-047"\n    assert (\n        composition.production_persistence_router\n        is persistence_router\n    )\n    assert (\n        composition.scheduler_cycle_callable\n        is scheduler_callable\n    )\n    assert (\n        composition\n        .production_wiring\n        .production_persistence_router\n        is persistence_router\n    )\n    assert (\n        composition\n        .scheduler_adapter\n        .scheduler_cycle_callable\n        is scheduler_callable\n    )\n    assert (\n        composition\n        .completion_bridge\n        .production_wiring\n        is composition.production_wiring\n    )\n    assert (\n        composition\n        .scheduler_adapter\n        .lineage_completion_bridge\n        is composition.completion_bridge\n    )\n    assert (\n        composition.staged_persistence_router\n        is composition\n        .production_wiring\n        .staged_persistence_router\n    )\n\n    return composition\n\n\ndef stage_cycle(\n    composition,\n    *,\n    cycle_number,\n    observed_at,\n    changed_market=None,\n):\n    composition.staged_persistence_router.route_batch(\n        build_cohort(\n            cycle_number=cycle_number,\n            changed_market=changed_market,\n        ),\n        observed_at,\n    )\n\n\ndef run_three_cycle_shared_state_test():\n    composition = run_composition_identity_test()\n\n    receipts = []\n\n    for cycle_number, observed_at, changed_market in (\n        (1, T1, None),\n        (2, T2, None),\n        (\n            3,\n            T3,\n            "KXTEST-COMPOSE-3",\n        ),\n    ):\n        stage_cycle(\n            composition,\n            cycle_number=cycle_number,\n            observed_at=observed_at,\n            changed_market=changed_market,\n        )\n\n        result = composition.scheduler_adapter(\n            cycle_completed_at=observed_at,\n            cycle_kwargs={\n                "cycle": cycle_number,\n            },\n        )\n\n        assert result["scheduler_projection"] == "preserved"\n        assert result["kwargs_echo"] == {\n            "cycle": cycle_number,\n        }\n\n        receipts.append(\n            composition.scheduler_adapter.last_receipt\n        )\n\n    assert (\n        receipts[0]\n        .lineage_completion_receipt\n        .lineage_wiring_receipt\n        .lineage_record_count_after\n        == 5\n    )\n    assert (\n        receipts[1]\n        .lineage_completion_receipt\n        .lineage_wiring_receipt\n        .lineage_record_count_after\n        == 10\n    )\n    assert (\n        receipts[2]\n        .lineage_completion_receipt\n        .lineage_wiring_receipt\n        .lineage_record_count_after\n        == 15\n    )\n    assert (\n        receipts[2]\n        .lineage_completion_receipt\n        .lineage_wiring_receipt\n        .transition_count\n        == 1\n    )\n\n    ledger = (\n        composition\n        .production_wiring\n        .lineage_bridge\n        .coordinator\n        .lineage_cycle_bridge\n        .batch_router\n        .bridge\n        .ledger\n    )\n\n    changed = ledger.head(\n        source_id="source.kalshi.market_data",\n        source_market_id="KXTEST-COMPOSE-3",\n    )\n    unchanged = ledger.head(\n        source_id="source.kalshi.market_data",\n        source_market_id="KXTEST-COMPOSE-1",\n    )\n\n    assert changed is not None\n    assert unchanged is not None\n    assert changed.transition_detected is True\n    assert changed.state_changed_at == T3\n    assert changed.consecutive_frame_count == 1\n    assert changed.dwell_seconds == "0.000000"\n    assert unchanged.consecutive_frame_count == 3\n    assert unchanged.dwell_seconds == "30.000000"\n\n    return composition, receipts\n\n\ndef run_deterministic_composition_replay_test():\n    def execute():\n        composition, _, _ = build_composition()\n        receipts = []\n\n        for cycle_number, observed_at, changed_market in (\n            (1, T1, None),\n            (2, T2, None),\n            (\n                3,\n                T3,\n                "KXTEST-COMPOSE-5",\n            ),\n        ):\n            stage_cycle(\n                composition,\n                cycle_number=cycle_number,\n                observed_at=observed_at,\n                changed_market=changed_market,\n            )\n\n            composition.scheduler_adapter(\n                cycle_completed_at=observed_at,\n                cycle_kwargs={\n                    "cycle": cycle_number,\n                },\n            )\n\n            receipts.append(\n                composition.scheduler_adapter.last_receipt\n            )\n\n        records = (\n            composition\n            .production_wiring\n            .lineage_bridge\n            .coordinator\n            .lineage_cycle_bridge\n            .batch_router\n            .bridge\n            .ledger\n            .records()\n        )\n\n        return tuple(receipts), records\n\n    first_receipts, first_records = execute()\n    second_receipts, second_records = execute()\n\n    assert first_receipts == second_receipts\n    assert first_records == second_records\n\n    return first_receipts, first_records\n\n\ndef main():\n    composition, receipts = (\n        run_three_cycle_shared_state_test()\n    )\n\n    replay_receipts, replay_records = (\n        run_deterministic_composition_replay_test()\n    )\n\n    receipt = composition.receipt\n\n    result = {\n        "schema_version": receipt.schema_version,\n        "engine_id": receipt.engine_id,\n        "status": "passed",\n        "production_persistence_router_preserved": True,\n        "scheduler_cycle_callable_preserved": True,\n        "ola_042_staged_router_exposed_for_dual_injection": True,\n        "ola_044_shared_production_wiring_created_once": True,\n        "ola_045_completion_bridge_shared": True,\n        "ola_046_scheduler_adapter_shared": True,\n        "shared_lineage_state_preserved_across_cycles": True,\n        "first_cycle_lineage_record_count": (\n            receipts[0]\n            .lineage_completion_receipt\n            .lineage_wiring_receipt\n            .lineage_record_count_after\n        ),\n        "second_cycle_lineage_record_count": (\n            receipts[1]\n            .lineage_completion_receipt\n            .lineage_wiring_receipt\n            .lineage_record_count_after\n        ),\n        "third_cycle_lineage_record_count": (\n            receipts[2]\n            .lineage_completion_receipt\n            .lineage_wiring_receipt\n            .lineage_record_count_after\n        ),\n        "third_cycle_transition_count": (\n            receipts[2]\n            .lineage_completion_receipt\n            .lineage_wiring_receipt\n            .transition_count\n        ),\n        "scheduler_kwargs_unchanged": True,\n        "scheduler_results_unchanged": True,\n        "deterministic_composition_replay_valid": (\n            len(replay_receipts) == 3\n            and len(replay_records) == 15\n        ),\n        "no_acquisition_owned": True,\n        "no_persistence_owned": True,\n        "no_intelligence_interpretation": True,\n        "no_signal_scoring": True,\n        "alerts_allowed": False,\n        "qseries_handoff_allowed": False,\n        "read_only": receipt.read_only,\n        "execution_allowed": receipt.execution_allowed,\n        "execution_adapter_resolved": (\n            receipt.execution_adapter_resolved\n        ),\n        "execution_adapter_invoked": (\n            receipt.execution_adapter_invoked\n        ),\n        "trade_authorization_allowed": (\n            receipt.trade_authorization_allowed\n        ),\n        "order_placement_allowed": (\n            receipt.order_placement_allowed\n        ),\n        "funds_moved": receipt.funds_moved,\n        "portfolio_mutated": receipt.portfolio_mutated,\n    }\n\n    print(\n        "[PASS] OLA-047 Oracle Scheduler Lineage "\n        "Production Composition"\n    )\n    print(result)\n\n\nif __name__ == "__main__":\n    main()\n'


def write_full_replacement(path: Path, source: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(
        source,
        encoding="utf-8",
        newline="\n",
    )
    print(f"[OK] FULL REPLACEMENT: {path}")


def main() -> None:
    print("========================================")
    print(" OLA-047 INSTALLER")
    print(" SCHEDULER LINEAGE PROD COMPOSITION")
    print("========================================")

    write_full_replacement(
        PRODUCTION_PATH,
        PRODUCTION_SOURCE,
    )
    write_full_replacement(
        TEST_PATH,
        TEST_SOURCE,
    )

    print()
    print(
        "[DONE] OLA-047 Oracle Scheduler Lineage "
        "Production Composition installed"
    )
    print()
    print("Run:")
    print(
        "py test_ola_047_oracle_scheduler_"
        "lineage_production_composition.py"
    )


if __name__ == "__main__":
    main()
